cases.command:
db=${XDG_STATE_HOME:-$HOME/.local/state}/aico/notes.db; ls -la $db; python3 -c "
import sqlite3; c=sqlite3.connect('file:$db?mode=ro',uri=True)
for r in c.execute(\"select id,ask_id,kind,name,status,deleted,datetime(created_at/1000,'unixepoch','localtime'),datetime(updated_at/1000,'unixepoch','localtime'),origin from captures order by created_at desc limit 15\"): print(r)"

cd /srv/workspaces/projects/summitflow/.git/st/acceptance/isolated-observations && d=$(ls -td */ | head -1); echo $d; python3 -c "
import xml.etree.ElementTree as E,sys
t=E.parse('${d}native-python.xml')
for tc in t.iter('testcase'):
  for f in list(tc):
    if f.tag in ('failure','error'): print(tc.get('classname'),tc.get('name'),'|',(f.get('message') or '')[:150].replace(chr(10),' '))
"; uptime

echo "widget=$AICO_WIDGET_ID"; cd /srv/workspaces/projects/aico/tether/scripts && python3 aico-root-watch.py sessions 2>&1 | python3 -c "
import json,sys,os
d=json.load(sys.stdin)
for s in d.get('sessions',[]):
  if s.get('id')==os.environ.get('AICO_WIDGET_ID') or s.get('widgetId')==os.environ.get('AICO_WIDGET_ID'): print(json.dumps(s))
"
